WITH session_summary AS (SELECT session_id, ROUND((100 * SUM(CASE WHEN event_type = 'purchase' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_purchase, COUNT(CASE WHEN page = '/search' THEN 1 END) search_count FROM web_events WHERE event_type NOT IN ('page_view', 'purchase', 'click') GROUP BY session_id) SELECT sessions.id, sessions.started_at, sessions.device, session_summary.pct_purchase, session_summary.search_count FROM sessions INNER JOIN session_summary ON sessions.id = session_summary.session_id WHERE session_summary.search_count > 6 ORDER BY sessions.id DESC
